"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { FALLBACK_VOICES } from "@/lib/add-voice-data"

/**
 * Picks the voice that covers this one when its provider goes down.
 *
 * A popover rather than a nested dialog: the choice is one tap on a short list
 * of voices that already exist, and stacking a second modal over the one being
 * filled in loses the row it is changing.
 *
 * Each row names the voice's gender, not its provider — the row behind the
 * popover already carries the provider, and while choosing, gender is what a
 * fallback is matched on.
 *
 * Choosing closes the popover. There is nothing else in it to do, so a row that
 * selects and then waits for the reader to dismiss it asks for a second click
 * that decides nothing.
 */
export function FallbackVoicePicker({
  onValueChange,
  value,
}: {
  onValueChange: (voiceId: string) => void
  value: string
}) {
  const [open, setOpen] = React.useState(false)

  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PopoverTrigger asChild>
        <Button variant="outline">Change voice</Button>
      </PopoverTrigger>

      <PopoverContent align="start" className="w-80">
        <RadioGroup
          className="gap-0"
          onValueChange={(voiceId) => {
            onValueChange(voiceId)
            setOpen(false)
          }}
          value={value}
        >
          {FALLBACK_VOICES.map((voice) => (
            <Label
              className="items-start gap-3 rounded-md px-2 py-1.5 font-normal transition-colors duration-150 hover:bg-accent motion-reduce:transition-none"
              htmlFor={`fallback-${voice.id}`}
              key={voice.id}
            >
              {/* The radio is text-sized, so it centres on the name rather
                  than on the two-line block. */}
              <RadioGroupItem
                className="mt-1"
                id={`fallback-${voice.id}`}
                value={voice.id}
              />
              <span className="flex flex-col gap-0.5">
                <span className="text-base font-medium">{voice.name}</span>
                <span className="text-muted-foreground">
                  {voice.vibe} · {voice.gender}
                </span>
              </span>
            </Label>
          ))}
        </RadioGroup>
      </PopoverContent>
    </Popover>
  )
}

import { InformationCircleIcon } from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/** Carries the explanation of what the fallback voice is for. */
export const FieldHelpIcon = icon(InformationCircleIcon, "FieldHelpIcon")

"use client"

import {
  ArrowLeft02Icon,
  ArrowRight02Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BookOpen01Icon,
  Cancel01Icon,
  CircleQuestionMarkIcon,
  ComputerTerminal01Icon,
  Copy01Icon,
  Link04Icon,
  Search01Icon,
  SourceCodeIcon,
  Tick02Icon,
  TranslateIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/**
 * Icons for the workspace itself — the index and the shell around every
 * mockup. Icons *inside* a mockup live in that mockup's own icons.tsx; this
 * file is only the chrome.
 */
export const BackIcon = icon(ArrowLeft02Icon, "BackIcon")
export const OpenIcon = icon(ArrowRight02Icon, "OpenIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")
export const ClearIcon = icon(Cancel01Icon, "ClearIcon")
export const DirectionIcon = icon(TranslateIcon, "DirectionIcon")

/* Beside the ticket ID in a card's footer, so it reads as something that
   leaves the page rather than as another in-page action. */
export const TicketLinkIcon = icon(ArrowUpRight01Icon, "TicketLinkIcon")

/* On the dock at the foot of the index, pointing at the list of surfaces
   that opens above it. */
export const DockIcon = icon(ArrowUp01Icon, "DockIcon")

/* The registry menu on an index card: the trigger, and the copy affordance
   that swaps to a tick once the command is on the clipboard. */
export const RegistryIcon = icon(SourceCodeIcon, "RegistryIcon")
export const CopyIcon = icon(Copy01Icon, "CopyIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* On the index header, next to the search field — the way into the design
   system, which has no card in the list below. */
export const RulesIcon = icon(BookOpen01Icon, "RulesIcon")

/* Opens the card's links — the mockup's own URL and the tickets it answers —
   for copying rather than for following. */
export const ShareLinkIcon = icon(Link04Icon, "ShareLinkIcon")

/* The index header's way back into the registry walkthrough, and the terminal
   the walkthrough's last step is about. */
export const HelpIcon = icon(CircleQuestionMarkIcon, "HelpIcon")
export const TerminalIcon = icon(ComputerTerminal01Icon, "TerminalIcon")
